 en:{todayAddresses:'Today’s addresses',todayAddressesSub:'Where to go and when',emptyTodayAddresses:'No addresses scheduled today',openMaps:'Open in Maps',monthReport:'Monthly financial report',chooseMonth:'Select month',spendingBreakdown:'Spending by category',noBreakdown:'No expenses for this month',voiceDeleteChoose:'Choose the appointment to delete',voiceDeleteNotFound:'No matching appointment found',confirmDeleteTask:'Delete this appointment?',monthReportShown:'Monthly financial report displayed',appInstall:'Install app',installHelp:'On Android Chrome, open ⋮ → Add to Home screen → Install app, not Create shortcut. Shortcuts open in Chrome. Check uploaded files if Install app is missing. This is a web app, not an APK.',monthlyReportTip:'Totals use the selected currency only and are not your bank account balance.'},
